def max_aggregate(data):
    # Dictionary to store the aggregate scores
    aggregate_scores = {}

    # Calculate the aggregate for each person
    for name, score in data:
        if name in aggregate_scores:
            aggregate_scores[name] += score
        else:
            aggregate_scores[name] = score

    # Find the name with the maximum aggregate score
    max_person = max(aggregate_scores, key=aggregate_scores.get)
    return (max_person, aggregate_scores[max_person])

# Example test
assert max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)]) == ('Juan Whelan', 212)
```

