def move_num(s):
    letters = []
    numbers = []

    current_number = ""

    for char in s:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                numbers.append(current_number)
                current_number = ""
            letters.append(char)

    if current_number:
        numbers.append(current_number)

    return ''.join(letters) + ''.join(numbers)

# Example usage and testing
assert move_num('I1love143you55three3000thousand') == 'Iloveyouthreethousand1143553000'
