def find_sum(lst):
    # Create a dictionary to count the occurrences of each element
    count = {}
    for num in lst:
        count[num] = count.get(num, 0) + 1

    # Sum the elements that appear only once
    return sum(num for num, occurrences in count.items() if occurrences == 1)

# Test
assert find_sum([1, 2, 3, 1, 1, 4, 5, 6]) == 21
